"""User-friendly entry page for J Book Translate."""
from __future__ import annotations

from app.core.fonts import embedded_vazirmatn_font_faces


def welcome_page() -> str:
    fonts = embedded_vazirmatn_font_faces()
    return f'''<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f5f7fb"><title>شروع | J Book Translate</title>{fonts}<style>
:root{{--bg:#f5f7fb;--surface:#fff;--surface-soft:#f9fbff;--ink:#17243a;--muted:#68778e;--line:#e1e7f0;--primary:#356df6;--primary-dark:#2859d2;--purple:#7257e8;--green:#0b956c;--red:#d94a4a;--shadow:0 20px 65px rgba(36,56,91,.11)}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;min-height:100vh;background:radial-gradient(circle at 8% 0,#e6eeff 0,transparent 32%),radial-gradient(circle at 96% 8%,#eee9ff 0,transparent 28%),var(--bg);color:var(--ink);font:14px Vazirmatn,Tahoma,sans-serif}}body.dark{{--bg:#141a24;--surface:#1d2633;--surface-soft:#19212d;--ink:#ecf2fb;--muted:#a8b5c7;--line:#344154;--primary:#7da2ff;--primary-dark:#668eea;--purple:#a58ef5;--green:#53c99f;--red:#ff8585;--shadow:0 22px 65px rgba(0,0,0,.28)}}a,button{{font:inherit}}a:focus-visible,button:focus-visible{{outline:3px solid #7da2ff;outline-offset:3px}}.shell{{width:min(1180px,calc(100% - 32px));margin:auto;padding:18px 0 64px}}.topbar{{position:sticky;top:12px;z-index:5;display:flex;align-items:center;gap:18px;padding:12px 14px;border:1px solid color-mix(in srgb,var(--line) 90%,transparent);border-radius:18px;background:color-mix(in srgb,var(--surface) 88%,transparent);backdrop-filter:blur(14px);box-shadow:0 10px 32px rgba(36,56,91,.07)}}.brand{{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink);margin-inline-end:auto}}.mark{{width:40px;height:40px;display:grid;place-items:center;border-radius:13px;background:linear-gradient(140deg,var(--primary),var(--purple));color:#fff;font-size:20px;box-shadow:0 8px 18px rgba(53,109,246,.28)}}.brand strong{{display:block;font-size:14px}}.brand small{{display:block;color:var(--muted);font-size:10px}}.nav{{display:flex;align-items:center;gap:5px}}.nav a,.theme{{border:0;background:transparent;text-decoration:none;color:var(--muted);padding:9px 12px;border-radius:10px;cursor:pointer;font-weight:600}}.nav a:hover,.theme:hover{{background:var(--surface-soft);color:var(--ink)}}.nav .workspace-link{{background:var(--ink);color:var(--surface)}}.hero{{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(330px,.85fr);gap:38px;align-items:center;padding:80px 24px 58px}}.eyebrow{{display:inline-flex;align-items:center;gap:8px;color:var(--primary-dark);background:color-mix(in srgb,var(--primary) 10%,transparent);border:1px solid color-mix(in srgb,var(--primary) 18%,transparent);border-radius:999px;padding:7px 11px;font-size:12px;font-weight:700}}.eyebrow i{{width:7px;height:7px;border-radius:50%;background:var(--green)}}h1{{max-width:720px;margin:18px 0 16px;font-size:clamp(36px,5.3vw,68px);line-height:1.25;letter-spacing:-1.5px}}h1 span{{color:var(--primary)}}.lead{{max-width:650px;color:var(--muted);font-size:16px;line-height:2;margin:0}}.actions{{display:flex;gap:10px;flex-wrap:wrap;margin-top:28px}}.button{{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:48px;padding:11px 20px;border:1px solid var(--line);border-radius:12px;background:var(--surface);color:var(--ink);text-decoration:none;font-weight:800;box-shadow:0 7px 20px rgba(36,56,91,.05)}}.button.primary{{border-color:transparent;background:linear-gradient(135deg,var(--primary),var(--purple));color:#fff;box-shadow:0 12px 28px rgba(53,109,246,.25)}}.trust{{display:flex;gap:18px;flex-wrap:wrap;margin-top:24px;color:var(--muted);font-size:12px}}.trust span:before{{content:'✓';color:var(--green);font-weight:900;margin-inline-end:6px}}.overview{{position:relative;padding:20px;border:1px solid var(--line);border-radius:26px;background:linear-gradient(160deg,color-mix(in srgb,var(--surface) 96%,transparent),color-mix(in srgb,var(--surface-soft) 90%,transparent));box-shadow:var(--shadow)}}.overview:before{{content:'';position:absolute;inset:-18px 14% auto;height:72px;background:var(--primary);filter:blur(55px);opacity:.13;z-index:-1}}.overview-head{{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}}.overview-head strong{{font-size:16px}}.status{{display:inline-flex;align-items:center;gap:7px;color:var(--muted);font-size:11px}}.status i{{width:8px;height:8px;border-radius:50%;background:#a8b3c3}}.status.ready i{{background:var(--green);box-shadow:0 0 0 4px color-mix(in srgb,var(--green) 16%,transparent)}}.status.error i{{background:var(--red)}}.metrics{{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}}.metric{{padding:16px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}}.metric span{{display:block;color:var(--muted);font-size:11px}}.metric strong{{display:block;margin-top:5px;font-size:24px}}.recent{{margin-top:12px;padding:15px;border:1px solid var(--line);border-radius:14px;background:var(--surface)}}.recent-head{{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px}}.recent-head strong{{font-size:12px}}.recent-head a{{font-size:11px;color:var(--primary);text-decoration:none}}.recent-list{{display:grid;gap:7px}}.recent-item{{display:flex;align-items:center;gap:9px;padding:9px;border-radius:10px;background:var(--surface-soft)}}.recent-icon{{width:30px;height:30px;display:grid;place-items:center;border-radius:8px;background:color-mix(in srgb,var(--primary) 10%,transparent);color:var(--primary)}}.recent-copy{{min-width:0;flex:1}}.recent-copy strong{{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px}}.recent-copy span{{color:var(--muted);font-size:10px}}.section{{padding:58px 24px}}.section-title{{max-width:650px;margin-bottom:24px}}.section-title span{{color:var(--primary);font-size:12px;font-weight:800}}.section-title h2{{font-size:clamp(25px,3vw,36px);margin:7px 0 8px}}.section-title p{{color:var(--muted);line-height:1.9;margin:0}}.steps,.features{{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}}.card{{padding:23px;border:1px solid var(--line);border-radius:18px;background:color-mix(in srgb,var(--surface) 94%,transparent);box-shadow:0 10px 32px rgba(36,56,91,.045)}}.step-number{{width:36px;height:36px;display:grid;place-items:center;border-radius:11px;color:#fff;background:linear-gradient(135deg,var(--primary),var(--purple));font-weight:800}}.card h3{{font-size:16px;margin:17px 0 8px}}.card p{{color:var(--muted);line-height:1.9;margin:0;font-size:12px}}.feature-icon{{font-size:24px}}.footer{{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-top:42px;padding:22px 24px;border-top:1px solid var(--line);color:var(--muted);font-size:11px}}.empty{{color:var(--muted);font-size:11px;padding:8px}}@media(max-width:880px){{.hero{{grid-template-columns:1fr;padding-top:55px}}.overview{{max-width:620px}}.steps,.features{{grid-template-columns:1fr 1fr}}}}@media(max-width:600px){{.shell{{width:min(100% - 20px,1180px)}}.topbar{{top:7px}}.brand small,.nav a:not(.workspace-link){{display:none}}.nav{{gap:2px}}.nav a,.theme{{padding:9px 10px}}.hero{{padding:48px 8px 35px;gap:30px}}h1{{font-size:36px;letter-spacing:-.8px}}.lead{{font-size:14px}}.actions .button{{width:100%}}.steps,.features{{grid-template-columns:1fr}}.section{{padding:42px 8px}}.footer{{display:block;padding:20px 8px}}}}@media(prefers-reduced-motion:reduce){{html{{scroll-behavior:auto}}}}
</style></head><body><div class="shell"><header class="topbar"><a class="brand" href="/"><span class="mark">文</span><span><strong>J Book Translate</strong><small>فضای ترجمه و مطالعهٔ کتاب</small></span></a><nav class="nav" aria-label="ناوبری اصلی"><a href="#features">امکانات</a><a href="/library">کتابخانه</a><a class="workspace-link" href="/workspace">ورود به میز کار</a><button class="theme" id="theme" type="button" aria-label="تغییر پوسته">◐</button></nav></header><main><section class="hero"><div><span class="eyebrow"><i></i><span id="welcome-status">برنامه روی همین دستگاه اجرا می‌شود</span></span><h1>ترجمهٔ کتاب، <span>مرتب و قابل ادامه</span></h1><p class="lead">کتاب EPUB یا PDF را اضافه کن، اصطلاحات تخصصی را ثابت نگه دار و پیشرفت ترجمه را حتی بعد از بستن صفحه دنبال کن.</p><div class="actions"><a class="button primary" href="/workspace#new-translation">＋ شروع ترجمهٔ جدید</a><a class="button" href="/workspace#active-jobs">مشاهدهٔ کارهای من</a></div><div class="trust"><span>ذخیره بعد از هر بخش</span><span>توقف امن و ادامهٔ کار</span><span>پردازش فایل‌ها به‌صورت محلی</span></div></div><aside class="overview" aria-label="خلاصهٔ وضعیت برنامه"><div class="overview-head"><strong>وضعیت فضای کاری</strong><span class="status" id="api-status"><i></i><span>در حال بررسی…</span></span></div><div class="metrics"><div class="metric"><span>ترجمه‌های فعال</span><strong id="active">۰</strong></div><div class="metric"><span>کتاب‌های کتابخانه</span><strong id="books">۰</strong></div><div class="metric"><span>تکمیل‌شده</span><strong id="completed">۰</strong></div><div class="metric"><span>متوقف‌شده</span><strong id="paused">۰</strong></div></div><div class="recent"><div class="recent-head"><strong>آخرین کارها</strong><a href="/workspace#active-jobs">مشاهدهٔ همه</a></div><div class="recent-list" id="recent"><span class="empty">در حال دریافت اطلاعات…</span></div></div></aside></section><section class="section"><div class="section-title"><span>شروع سریع</span><h2>در سه مرحله ترجمه را شروع کن</h2><p>تنظیمات پیش‌فرض برای بیشتر کتاب‌ها مناسب‌اند و هر زمان لازم باشد گزینه‌های تخصصی در دسترس‌اند.</p></div><div class="steps"><article class="card"><span class="step-number">۱</span><h3>کتاب را انتخاب کن</h3><p>فایل EPUB یا PDF را بکش و داخل صفحه رها کن یا از دستگاه انتخابش کن.</p></article><article class="card"><span class="step-number">۲</span><h3>زبان و مدل را مشخص کن</h3><p>زبان مبدأ و مقصد، مدل ترجمه و ساخت خودکار واژه‌نامه را تنظیم کن.</p></article><article class="card"><span class="step-number">۳</span><h3>پیشرفت را دنبال کن</h3><p>بین صفحات جابه‌جا شو؛ Job در پس‌زمینه ادامه پیدا می‌کند و وضعیت آن ذخیره می‌شود.</p></article></div></section><section class="section" id="features"><div class="section-title"><span>برای یک کتاب کامل</span><h2>همه‌چیز در یک فضای کاری</h2></div><div class="features"><article class="card"><span class="feature-icon">▣</span><h3>کتابخانهٔ منظم</h3><p>نسخهٔ اصلی، ترجمه‌شده، وضعیت و فایل‌های خروجی هر کتاب کنار هم نگهداری می‌شوند.</p></article><article class="card"><span class="feature-icon">文</span><h3>واژه‌نامهٔ ثابت</h3><p>نام شخصیت‌ها و اصطلاحات تخصصی در طول کتاب با ترجمهٔ یکسان استفاده می‌شوند.</p></article><article class="card"><span class="feature-icon">◫</span><h3>Reader دوزبانه</h3><p>متن اصلی و ترجمه را جدا یا کنار هم بخوان و تنظیمات مطالعه را شخصی‌سازی کن.</p></article></div></section></main><footer class="footer"><span>J Book Translate · فضای محلی ترجمهٔ کتاب</span><span>فایل‌ها و کلید API در مرورگر نمایش داده نمی‌شوند.</span></footer></div><script>
const $=s=>document.querySelector(s),fa=n=>new Intl.NumberFormat('fa-IR').format(n||0),statuses={{queued:'در صف',running:'در حال ترجمه',stopping:'در حال توقف',paused:'متوقف‌شده',stopped:'متوقف‌شده',completed:'تکمیل‌شده',finished:'پایان‌یافته',failed:'خطادار'}};
function escapeHtml(value){{return String(value).replace(/[&<>"']/g,char=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}})[char])}}
function applyTheme(){{const dark=localStorage.getItem('jbook-study-dark')==='1';document.body.classList.toggle('dark',dark);$('#theme').textContent=dark?'☀':'◐';$('#theme').setAttribute('aria-pressed',String(dark))}}
$('#theme').onclick=()=>{{localStorage.setItem('jbook-study-dark',document.body.classList.contains('dark')?'0':'1');applyTheme()}};applyTheme();
document.querySelector('.overview-head').insertAdjacentHTML('afterend','<a id="api-fix" class="button" href="/account#settings" style="display:none;margin:0 0 14px;min-height:38px">رفع تنظیمات سرویس ترجمه</a>');
async function loadSummary(){{try{{const [summaryResponse,jobsResponse,healthResponse]=await Promise.all([fetch('/api/dashboard/summary'),fetch('/api/jobs'),fetch('/api/health')]);if(!summaryResponse.ok||!jobsResponse.ok||!healthResponse.ok)throw Error();const summary=await summaryResponse.json(),jobs=await jobsResponse.json(),health=await healthResponse.json();$('#active').textContent=fa(summary.active_jobs);$('#books').textContent=fa(summary.total_books);$('#completed').textContent=fa(summary.completed_jobs);$('#paused').textContent=fa(summary.paused_jobs);const status=$('#api-status');status.className='status '+(health.status==='ready'?'ready':'error');status.querySelector('span').textContent=health.message;$('#api-fix').style.display=health.status==='ready'?'none':'inline-flex';$('#welcome-status').textContent=summary.active_jobs?fa(summary.active_jobs)+' ترجمه در حال اجراست':'آمادهٔ شروع ترجمه';const recent=(jobs.items||[]).sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||''))).slice(0,3);$('#recent').innerHTML=recent.length?recent.map(job=>`<div class="recent-item"><span class="recent-icon">${{job.filetype==='pdf'?'P':'E'}}</span><span class="recent-copy"><strong>${{escapeHtml(job.filename)}}</strong><span>${{statuses[job.status]||escapeHtml(job.status)}} · ${{fa(job.progress?.percent||0)}}٪</span></span></div>`).join(''):'<span class="empty">هنوز کاری ثبت نشده است.</span>'}}catch{{const status=$('#api-status');status.className='status error';status.querySelector('span').textContent='دریافت وضعیت ممکن نشد';$('#api-fix').style.display='inline-flex';$('#recent').innerHTML='<span class="empty">برای مشاهدهٔ وضعیت وارد میز کار شوید.</span>'}}}}
loadSummary();setInterval(loadSummary,10000);
</script></body></html>'''
